 NSString *path=[@"/private/tmp/lighting-file-" stringByAppendingString:NSUUID.UUID.UUIDString],*message=nil;assert(lightingFileWrite(@"example.m3i",source,path,&message));assert([[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil][NSFileSize] unsignedLongLongValue]==408);assert(lightingFileRead(path,@"example.m3i",target,&result,&message));assert(!(result.lights[0].option&1)&&result.lights[0].amplitude==2.5);assert((result.lights[1].option&5)==5&&result.lights[1].position[0]==3.25);assert(result.gamma==17&&fabs(result.object.diffuse-3.1)<1e-9);assert(!memcmp(&result.camera,&target.camera,sizeof target.camera)&&!memcmp(&result.program,&target.program,sizeof target.program));target.lights[0].option=4;target.lights[0].amplitude=7;target.lights[0].position[1]=9;target.lights[1].option=1;assert(lightingFileReadKeepingLights(path,@"example.m3i",target,YES,&result,&message));assert(!memcmp(result.lights,target.lights,sizeof target.lights));assert(result.gamma==17&&fabs(result.object.diffuse-3.1)<1e-9);assert(!memcmp(&result.camera,&target.camera,sizeof target.camera));assert((result.preserved_header[500]&5)==4);[NSFileManager.defaultManager removeItemAtPath:path error:nil];puts("Original .m3l saves 408 bytes, imports directionals, disables positional lights and preserves camera/formulas");
